from collections import deque
def comps(g):
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[]
                while q:
                    y,x=q.popleft(); c.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx] and (ny,nx) not in seen:
                                seen.add((ny,nx)); q.append((ny,nx))
                out.append(c)
    return out
