def erase_shape(grid, shape):
    """The grid with every cell of the given component shape set to 0."""
    s=set(shape)
    return [[0 if (i,j) in s else v for j,v in enumerate(row)] for i,row in enumerate(grid)]

def pick(components, grid, key):
    """The component minimizing key(component, grid)."""
    return min(components, key=lambda c: key(c, grid))

def count_color(shape, grid, color):
    """How many cells of the component have the given color."""
    return sum(1 for y,x in shape if grid[y][x]==color)

def erase_rarest_color_shape(grid, color=9):
